questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: one time in each of three of the four intervals (0, p0), (p0, mid), (mid, q0), (q0, infinity). Category codes: 1 positive direction speeding up, 2 positive slowing down, 3 negative speeding up, 4 negative slowing down. Source: original. */
L: [[1,1,3,[1/2,3/2,4]],[2,1,4,[1/2,13/4,5]],[-1,1,5,[1/2,2,4]],[1,2,4,[5/2,7/2,5]],[-2,1,3,[1/2,3/2,4]],[1,1,5,[1/2,4,6]],[2,2,6,[1,3,5]],[-1,2,4,[5/2,7/2,5]],[-1,1,3,[1/2,5/2,4]],[-2,2,4,[1,5/2,7/2]]];
ix: 1+rand(10);
a0: L[ix][1]; p0: L[ix][2]; q0: L[ix][3]; tl: L[ix][4];
s: expand((a0)*t^3-3*(a0)*((p0)+(q0))/2*t^2+3*(a0)*(p0)*(q0)*t+(0));
v: diff(s,t); a: diff(v,t);
t1: tl[1]; v1: ev(v,t=t1); a1: ev(a,t=t1);
c1: if v1>0 then (if a1>0 then 1 else 2) else (if a1<0 then 3 else 4);
o1: [["ps1",is(c1=1),"positive direction, speeding up"],["pd1",is(c1=2),"positive direction, slowing down"],["ns1",is(c1=3),"negative direction, speeding up"],["nd1",is(c1=4),"negative direction, slowing down"]];
w1s: ["pd1","ps1","nd1","ns1"][c1];
w1d: ["ns1","nd1","ps1","pd1"][c1];
w1b: ["nd1","ns1","pd1","ps1"][c1];
t2: tl[2]; v2: ev(v,t=t2); a2: ev(a,t=t2);
c2: if v2>0 then (if a2>0 then 1 else 2) else (if a2<0 then 3 else 4);
o2: [["ps2",is(c2=1),"positive direction, speeding up"],["pd2",is(c2=2),"positive direction, slowing down"],["ns2",is(c2=3),"negative direction, speeding up"],["nd2",is(c2=4),"negative direction, slowing down"]];
w2s: ["pd2","ps2","nd2","ns2"][c2];
w2d: ["ns2","nd2","ps2","pd2"][c2];
w2b: ["nd2","ns2","pd2","ps2"][c2];
t3: tl[3]; v3: ev(v,t=t3); a3: ev(a,t=t3);
c3: if v3>0 then (if a3>0 then 1 else 2) else (if a3<0 then 3 else 4);
o3: [["ps3",is(c3=1),"positive direction, speeding up"],["pd3",is(c3=2),"positive direction, slowing down"],["ns3",is(c3=3),"negative direction, speeding up"],["nd3",is(c3=4),"negative direction, slowing down"]];
w3s: ["pd3","ps3","nd3","ns3"][c3];
w3d: ["ns3","nd3","ps3","pd3"][c3];
w3b: ["nd3","ns3","pd3","ps3"][c3];
